 for name,section in [('RESULTS.md','\n## Connected readout three independent records - 2026-10-11\n\n[Aggregate evidence](../artifacts/analog_asic/results/gf180_six_class_readout_v3_three_independent_records.json): same physical458MOS30MIM layout completes three independent50ms ten-bin records, expected native winners1/0/5, label capture and hold after EVALoff. References independent per record; native current fixtures rather than trained final synapses. Earlier three-bank common-reference timeout preserved; both reference isolation and output/initial timestep changed, so cause is not isolated. Reset offsets/cross-class coupling/score gain and exact ties remain unaccepted. Catalog revision45 retains20 modules/35 characterization assemblies; this supplement adds case coverage, not a new module or full-chip completion.\n'),('PROGRESS.md','\n2026-10-11: connected readout now completes all three independent nominal record/capture cases; compensation completes resident adaptation and physical RMS input formatting. Catalog revision45 has20 module sets/35 characterization assemblies. Native26-leaf global barrier building; full layout unfinished. Exact prior docs archived with readout-three-record supplement.\n')]:
  p=ROOT/'docs'/name;b=p.read_bytes();i=b.index(b'\n## ');p.write_bytes(b[:i]+section.encode()+b[i:])
 p=ROOT/'docs/ACTIVE_TASKS.md';b=p.read_bytes().replace(b'article_module_catalog_v44.json',b'article_module_catalog_v45.json').replace(b'catalog revision44',b'catalog revision45');b=re.sub(rb'\| Job status \|[^\r\n]+',b'| Job status | Compensated resident adaptation and native energy formatting complete; connected readout winners1/0/5 pass in three independent50ms records. Global25actor+queue barrier building(session6669) |',b,count=1);a=b.index(b'3. Threshold adder');end=b.index(b'\n\n**Milestone exit:',a);b=b[:a]+b'3. Compensated product/resident adaptation now has completed extracted sequence evidence; preserve write-release and age-step errors. Native candidate-minus-penalty energy formatting completes with known RMS ratio error. Connected analog readout now covers three independent50ms records with native winner/capture/hold. Next: global25actor+queue completion barrier, RMS clip/strength/write and adaptation expiry, then compact dense/full25actor assembly with actual inventory/interconnect. Carry known accuracy errors forward; avoid precision sweeps. Spacious characterization fixtures must not be replicated as dense resident area.'+b[end:];p.write_bytes(b)
 p=ROOT/'docs/project_spec.yaml';b=p.read_bytes();h,t=b.split(b'\ndocument:',1);h=h.replace(b'article_module_catalog_v44.json',b'article_module_catalog_v45.json');h=re.sub(rb'  live_sessions: [^\r\n]+',b'  live_sessions: [6669]',h,count=1);h=re.sub(rb'    next_action: [^\r\n]+',b'    next_action: global_actor_queue_barrier_RMS_strength_expiry_then_dense_full_layout',h,count=1);h=re.sub(rb'    report: [^\r\n]+',b'    report: artifacts/analog_asic/results/gf180_six_class_readout_v3_three_independent_records.json',h,count=1);p.write_bytes(h+b'\ndocument:'+t)
 print(json.dumps({'catalog':str(cp),'report':str(rp),'native_winners':[1,0,5]}))
